<?php require __DIR__.'/../_init.php'; $id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT); $s=$pdo->prepare("SELECT id,name,email,created_at FROM users WHERE id=? AND role='user'");$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Customer not found.');}adminHeader($r['name']); ?><p><?= e($r['email']) ?> · Joined <?= e($r['created_at']) ?></p><h2>Purchase history</h2><table><tr><th>Order</th><th>Total</th><th>Status</th><th>Payment</th></tr><?php $s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$id]);foreach($s as $o): ?><tr><td><a href="../orders/view.php?id=<?= (int)$o['id'] ?>">#<?= (int)$o['id'] ?></a></td><td>৳<?= e($o['total']) ?></td><td><?= e($o['status']) ?></td><td><?= e($o['payment_status']) ?></td></tr><?php endforeach ?></table><?php adminFooter(); ?>